<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>롯데월드타워 개념 설계 재구성 · grok-4.7</title>
<style>
:root{--bg:#0e1218;--panel:#171d27;--ink:#e8eef6;--muted:#9aa8b8;--line:#3a4a5e;--acc:#c9a36a;--acc2:#6eb5d0}
*{box-sizing:border-box}
html,body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 "Segoe UI",system-ui,sans-serif}
header{padding:16px 20px 8px;border-bottom:1px solid var(--line)}
h1{font-size:1.25rem;margin:0 0 4px;font-weight:650}
.sub{color:var(--muted);font-size:.85rem}
.badge{display:inline-block;background:#243044;color:var(--acc);padding:2px 8px;border-radius:99px;font-size:.75rem;letter-spacing:.04em}
nav{display:flex;gap:8px;padding:10px 20px;flex-wrap:wrap}
button,select{background:#1e2734;color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 12px;cursor:pointer;font:inherit}
button[aria-pressed="true"],button:focus-visible{outline:2px solid var(--acc);border-color:var(--acc)}
main{display:grid;grid-template-columns:minmax(280px,1fr) minmax(300px,1.2fr);gap:12px;padding:0 16px 20px}
@media(max-width:900px){main{grid-template-columns:1fr}}
section{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:12px;min-height:220px}
h2{font-size:1rem;margin:0 0 8px}
p.note{color:var(--muted);font-size:.8rem;margin:6px 0}
svg{width:100%;height:auto;background:#0c1118;border-radius:8px}
canvas{width:100%;height:420px;display:block;background:#0a0e14;border-radius:8px;touch-action:none}
.row{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:8px}
label{font-size:.85rem;color:var(--muted)}
footer{padding:8px 20px 24px;color:var(--muted);font-size:.78rem}
.legend{display:flex;gap:12px;font-size:.78rem;color:var(--muted);flex-wrap:wrap}
.sw{width:10px;height:10px;display:inline-block;margin-right:4px;vertical-align:middle}
</style>
</head>
<body>
<header>
  <h1>롯데월드타워 — 형태 발전 개념 재구성</h1>
  <p class="sub">높이 555 m · 지상 123층 · 위로 갈수록 기준층이 좁아지는 도자기 윤곽의 개념 모델. 공식 시공 도면이 아닙니다.
  <span class="badge">모델 grok-4.7</span></p>
</header>
<nav aria-label="보기">
  <button id="bDraw" aria-pressed="true">도면</button>
  <button id="bStage" aria-pressed="false">설계 단계</button>
  <button id="bFinal" aria-pressed="false">완성 형상</button>
</nav>
<main>
  <section id="left">
    <h2 id="leftTitle">도면 (개념)</h2>
    <div class="row">
      <label for="sheet">도면</label>
      <select id="sheet">
        <option value="site">배치도</option>
        <option value="plan">기준층 평면도</option>
        <option value="elev">입면도</option>
        <option value="sect">단면도</option>
      </select>
      <label for="level">기준층 위치</label>
      <select id="level">
        <option value="low">저층 (개념 Ø ~70 m)</option>
        <option value="mid">중층 (개념 Ø ~55 m)</option>
        <option value="high">고층 (개념 Ø ~40 m)</option>
      </select>
    </div>
    <svg id="sheetSvg" viewBox="0 0 640 420" role="img" aria-label="개념 도면"></svg>
    <p class="note" id="sheetNote"></p>
    <div class="legend">
      <span><i class="sw" style="background:#c9a36a"></i>외곽</span>
      <span><i class="sw" style="background:#6eb5d0"></i>코어(개념)</span>
      <span><i class="sw" style="background:#445566"></i>대지/기준선</span>
    </div>
  </section>
  <section>
    <h2 id="rightTitle">3D</h2>
    <div class="row" id="stageRow">
      <label for="stage">단계</label>
      <select id="stage">
        <option value="0">1 매스 — 수직 박스</option>
        <option value="1">2 테이퍼 — 선형 축소</option>
        <option value="2">3 윤곽 — 도자기 곡선</option>
        <option value="3">4 입면 — 수직 리브</option>
        <option value="4">5 완성 — 크라운·첨탑</option>
      </select>
      <button id="resetCam" type="button">시점 초기화</button>
    </div>
    <canvas id="view" aria-label="3D 모델. 드래그로 회전, 휠 또는 핀치로 확대"></canvas>
    <p class="note" id="stageNote">Orbit: 드래그 회전, 휠/핀치 확대, 우클릭 또는 두 손가락 이동. 키보드: 화살표 회전, +/- 확대, 0 초기화.</p>
  </section>
</main>
<footer>
  출처(텍스트): KPF 프로젝트 설명 — 한국 도자기 선을 형태·외관에 참고. LERA 구조 설계 참여.
  치수 중 555 m·123층만 공개 사실이며, 평면 직경·코어·리브·단면 위치는 형태를 이해하기 위한 추정치입니다.
  모델 표시명: grok-4.7
</footer>
<script src="../runtime/three-runtime.js"></script>
<script>
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const H = 555;
const stages = [
  {name:'수직 박스', note:'초기 용적: 동일 단면의 123층 개념 매스. 높이만 555 m로 고정.'},
  {name:'선형 테이퍼', note:'상부로 갈수록 기준층 면적이 줄어드는 원뿔대형. 외곽 축소의 1차 규칙.'},
  {name:'도자기 곡선', note:'KPF가 언급한 한국 도자기 윤곽을 부드러운 곡선 프로파일로 재구성. 중간이 살짝 배부른 뒤 상부에서 급히 좁아짐.'},
  {name:'수직 리브', note:'곡면 외피에 세로 리브를 더해 입면 방향성을 표현. 부재 크기·간격은 추정.'},
  {name:'크라운·첨탑', note:'상단 크라운과 첨탑을 포함한 완성 실루엣. 실제 디테일과 다를 수 있는 개념 형상.'}
];
function radiusAt(t){
  const base=36, top=14;
  const belly = Math.sin(t*Math.PI)*4.2*(1-t*0.35);
  return base + (top-base)*Math.pow(t,1.15) + belly*(t<0.85?1:0);
}
function buildMesh(stage){
  const g = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({color:0xd8c7a2,metalness:.25,roughness:.45,side:THREE.DoubleSide});
  const glass = new THREE.MeshStandardMaterial({color:0x8fb4c9,metalness:.4,roughness:.25,transparent:true,opacity:.85});
  const dark = new THREE.MeshStandardMaterial({color:0x2a3340,metalness:.2,roughness:.6});
  if(stage===0){
    const m=new THREE.Mesh(new THREE.BoxGeometry(62,H,62), mat);
    m.position.y=H/2; g.add(m);
  } else {
    const pts=[];
    const N=48;
    for(let i=0;i<=N;i++){
      const t=i/N;
      let r = stage===1 ? 36+(14-36)*t : radiusAt(t);
      pts.push(new THREE.Vector2(r, t*H));
    }
    if(stage>=4){
      pts.push(new THREE.Vector2(8, H+18));
      pts.push(new THREE.Vector2(1.2, H+48));
      pts.push(new THREE.Vector2(0.2, H+70));
    }
    const lathe=new THREE.LatheGeometry(pts, stage>=3?64:48);
    const mesh=new THREE.Mesh(lathe, stage>=3?glass:mat);
    g.add(mesh);
    if(stage>=3){
      for(let k=0;k<16;k++){
        const a=k/16*Math.PI*2;
        const rib=new THREE.Mesh(new THREE.BoxGeometry(1.1,H*0.92,2.2), dark);
        rib.position.set(Math.cos(a)*radiusAt(0.35), H*0.46, Math.sin(a)*radiusAt(0.35));
        rib.lookAt(0,rib.position.y,0);
        g.add(rib);
      }
    }
    if(stage>=4){
      const crown=new THREE.Mesh(new THREE.CylinderGeometry(16,22,16,32,1,true), mat);
      crown.position.y=H-6; g.add(crown);
    }
  }
  const podium=new THREE.Mesh(new THREE.BoxGeometry(90,18,70), dark);
  podium.position.y=9; g.add(podium);
  return g;
}
let renderer, scene, camera, controls, current;
function init3d(){
  const canvas=document.getElementById('view');
  renderer=new THREE.WebGLRenderer({canvas,antialias:!reduce});
  renderer.setPixelRatio(Math.min(devicePixelRatio,2));
  scene=new THREE.Scene();
  scene.background=new THREE.Color(0x0a0e14);
  scene.fog=new THREE.Fog(0x0a0e14,800,1800);
  camera=new THREE.PerspectiveCamera(40,1,1,4000);
  camera.position.set(280,220,340);
  const amb=new THREE.AmbientLight(0xffffff,.55);
  const dir=new THREE.DirectionalLight(0xfff4e0,1.1);
  dir.position.set(200,400,120);
  scene.add(amb,dir);
  const grid=new THREE.GridHelper(400,20,0x334455,0x1c2633);
  scene.add(grid);
  controls=new THREE.OrbitControls(camera, canvas);
  controls.target.set(0,H*0.35,0);
  controls.enableDamping=!reduce;
  setStage(4);
  resize();
  addEventListener('resize', resize);
  (function loop(){requestAnimationFrame(loop); if(controls.enableDamping) controls.update(); renderer.render(scene,camera);})();
}
function resize(){
  const c=renderer.domElement;
  const w=c.clientWidth, h=c.clientHeight;
  renderer.setSize(w,h,false);
  camera.aspect=w/Math.max(h,1); camera.updateProjectionMatrix();
}
function setStage(i){
  if(current) scene.remove(current);
  current=buildMesh(i); scene.add(current);
  document.getElementById('stageNote').textContent=stages[i].note+'  Orbit: 드래그 회전, 휠/핀치 확대. 키보드 화살표, +/- , 0.';
  document.getElementById('stage').value=String(i);
}
function resetCam(){
  camera.position.set(280,220,340);
  controls.target.set(0,H*0.35,0);
  controls.update();
}
const dims={low:70,mid:55,high:40};
function drawSheet(){
  const kind=document.getElementById('sheet').value;
  const lv=document.getElementById('level').value;
  const svg=document.getElementById('sheetSvg');
  const D=dims[lv];
  let s='', note='';
  if(kind==='site'){
    s=`<rect x="40" y="40" width="560" height="340" fill="none" stroke="#445566"/>
      <text x="50" y="64" fill="#9aa8b8" font-size="14">개념 배치 — 송파 한강변 부지 관계만 표시 (축척 없음)</text>
      <ellipse cx="360" cy="230" rx="70" ry="46" fill="#1a2430" stroke="#c9a36a" stroke-width="2"/>
      <text x="330" y="234" fill="#e8eef6" font-size="13">타워</text>
      <rect x="250" y="300" width="220" height="28" fill="#243044" stroke="#6eb5d0"/>
      <text x="300" y="318" fill="#9aa8b8" font-size="12">포디엄(개념)</text>
      <path d="M80 80 H200" stroke="#445566"/><text x="80" y="74" fill="#9aa8b8" font-size="12">북(개념)</text>`;
    note='배치도는 주변 도시 맥락의 자리만 보여 줍니다. 도로·대지 경계 치수는 공개 자료에 없어 표기하지 않습니다.';
  } else if(kind==='plan'){
    const r=D*2.2;
    s=`<text x="24" y="28" fill="#9aa8b8" font-size="14">기준층 평면 — ${lv==='low'?'저층':lv==='mid'?'중층':'고층'} · 외곽 직경 개념 ${D} m (추정)</text>
      <circle cx="320" cy="220" r="${r}" fill="#141c26" stroke="#c9a36a" stroke-width="2"/>
      <circle cx="320" cy="220" r="${r*0.28}" fill="none" stroke="#6eb5d0" stroke-width="2"/>
      <text x="292" y="224" fill="#6eb5d0" font-size="12">코어</text>
      <text x="24" y="400" fill="#9aa8b8" font-size="12">단위 m · 직경은 555 m 높이와 테이퍼 실루엣을 맞추기 위한 개념값</text>`;
    note='같은 평면도라도 층이 높아질수록 외곽이 줄어듭니다. 코어 비율은 구조 이해를 위한 가정입니다.';
  } else if(kind==='elev'){
    let d='';
    for(let i=0;i<=40;i++){
      const t=i/40, x=320-(radiusAt(t)/36)*150, y=380-t*340;
      d+=(i?'L':'M')+x+' '+y+' ';
    }
    for(let i=40;i>=0;i--){
      const t=i/40, x=320+(radiusAt(t)/36)*150, y=380-t*340;
      d+='L'+x+' '+y+' ';
    }
    s=`<text x="24" y="28" fill="#9aa8b8" font-size="14">입면 — 전체 높이 555 m (공개) · 가로 폭은 추정 프로파일</text>
      <path d="${d}Z" fill="#1a2430" stroke="#c9a36a"/>
      <line x1="80" y1="380" x2="80" y2="40" stroke="#6eb5d0"/>
      <text x="86" y="210" fill="#6eb5d0" font-size="12">555 m</text>
      <text x="24" y="408" fill="#9aa8b8" font-size="12">선택한 단계의 곡선과 같은 radiusAt(t) 함수를 사용</text>`;
    note='입면 실루엣은 3D 단계 3~5와 동일한 프로파일 함수입니다. 창호 모듈은 생략했습니다.';
  } else {
    s=`<text x="24" y="28" fill="#9aa8b8" font-size="14">종단면 개념 — 코어와 외곽의 관계 (부재 치수 추정)</text>
      <path d="M250 380 L270 40 L370 40 L390 380 Z" fill="#141c26" stroke="#c9a36a"/>
      <rect x="300" y="50" width="40" height="320" fill="none" stroke="#6eb5d0"/>
      <text x="400" y="210" fill="#9aa8b8" font-size="12">외곽 테이퍼</text>
      <text x="248" y="400" fill="#9aa8b8" font-size="12">123개 슬래브는 도식상 생략 · 높이 눈금 555 m</text>
      <line x1="200" y1="380" x2="200" y2="40" stroke="#445566"/>`;
    note='단면도는 좁아지는 임대 면적과 중앙 코어의 개념 관계만 보여 줍니다. 보·기둥 크기는 검증된 구조값이 아닙니다.';
  }
  svg.innerHTML=s;
  document.getElementById('sheetNote').textContent=note;
}
function show(mode){
  document.getElementById('bDraw').setAttribute('aria-pressed', mode==='draw');
  document.getElementById('bStage').setAttribute('aria-pressed', mode==='stage');
  document.getElementById('bFinal').setAttribute('aria-pressed', mode==='final');
  const left=document.getElementById('left');
  left.style.display = mode==='final' ? 'none' : '';
  if(mode==='draw'){
    document.getElementById('leftTitle').textContent='도면 (개념)';
    document.getElementById('sheet').parentElement.style.display='';
    drawSheet();
  }
  if(mode==='stage'){
    document.getElementById('leftTitle').textContent='단계와 도면의 대응';
    setStage(+document.getElementById('stage').value);
  }
  if(mode==='final'){
    setStage(4);
    document.getElementById('stage').value='4';
  }
}
document.getElementById('bDraw').onclick=()=>show('draw');
document.getElementById('bStage').onclick=()=>show('stage');
document.getElementById('bFinal').onclick=()=>show('final');
document.getElementById('sheet').onchange=drawSheet;
document.getElementById('level').onchange=()=>{drawSheet(); const map={low:0,mid:2,high:4};};
document.getElementById('stage').onchange=e=>setStage(+e.target.value);
document.getElementById('resetCam').onclick=resetCam;
addEventListener('keydown',e=>{
  if(e.target.tagName==='INPUT'||e.target.tagName==='SELECT') return;
  const step=e.shiftKey?20:8;
  if(e.key==='ArrowLeft') camera.position.applyAxisAngle(new THREE.Vector3(0,1,0), step*Math.PI/180);
  if(e.key==='ArrowRight') camera.position.applyAxisAngle(new THREE.Vector3(0,1,0), -step*Math.PI/180);
  if(e.key==='ArrowUp') camera.position.y+=step;
  if(e.key==='ArrowDown') camera.position.y-=step;
  if(e.key==='+'||e.key==='=') camera.position.multiplyScalar(0.9);
  if(e.key==='-'||e.key==='_') camera.position.multiplyScalar(1.1);
  if(e.key==='0') resetCam();
});
drawSheet();
init3d();
</script>
</body>
</html>
